mapper.select:
SELECT a.id, a.title, a.summary, a.content, a.category, a.tags, a.views, a.comments, a.likes, a.author_id, a.create_by, a.create_time, a.update_time, a.is_deleted FROM t_articles a
a.is_deleted = 0
AND YEAR ( a.create_time ) = #{searchYear}
AND DATE_FORMAT( a.create_time, '%Y-%m-%d' ) = #{searchDate}
ORDER BY a.create_time
